import{_ as r,o,c as s,a2 as t}from"./chunks/framework.CPzUcv0I.js";const p=JSON.parse('{"title":"Instances et Catalogue de Mods","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/players/instances-and-mods.md","filePath":"fr/guide/players/instances-and-mods.md"}'),a={name:"fr/guide/players/instances-and-mods.md"};function i(n,e,l,u,d,c){return o(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="instances-et-catalogue-de-mods" tabindex="-1">Instances et Catalogue de Mods <a class="header-anchor" href="#instances-et-catalogue-de-mods" aria-label="Permalink to &quot;Instances et Catalogue de Mods&quot;">​</a></h1><div style="display:flex;gap:8px;margin:1rem 0;flex-wrap:wrap;"><img src="https://img.shields.io/badge/Modloaders-Fabric%20%7C%20Forge%20%7C%20Quilt%20%7C%20NeoForge-blue.svg" alt="Modloaders"><img src="https://img.shields.io/badge/Catalogues-Modrinth%20%26%20CurseForge-green.svg" alt="Catalogues"></div><p>Gens Launcher propose une gestion complète et isolée de vos profils de jeu (« Instances »), inspirée des meilleurs outils du marché comme MultiMC et Prism Launcher, avec un accès direct aux catalogues de mods en ligne.</p><hr><h2 id="creer-une-instance" tabindex="-1">Créer une Instance <a class="header-anchor" href="#creer-une-instance" aria-label="Permalink to &quot;Créer une Instance&quot;">​</a></h2><ol><li>Dans le bandeau supérieur de l&#39;application, cliquez sur <strong>Nouvelle Instance</strong>.</li><li>Renseignez les paramètres de base : <ul><li><strong>Nom de l&#39;instance :</strong> Donnez un libellé clair (ex: <em>Survie 1.21 Fabric</em>).</li><li><strong>Version de Minecraft :</strong> Choisissez parmi toutes les versions disponibles (releases officielles, snapshots, versions historiques).</li><li><strong>Modloader :</strong> Sélectionnez le moteur de votre choix : <ul><li><strong>Vanilla :</strong> Aucun mod, jeu officiel pur.</li><li><strong>Fabric :</strong> Léger, moderne, idéal pour les mods d&#39;optimisation (Sodium, Lithium, Iris).</li><li><strong>Forge :</strong> Le modloader historique pour les gros modpacks techniques et magiques.</li><li><strong>Quilt :</strong> Fork moderne compatible avec la majorité des mods Fabric.</li><li><strong>NeoForge :</strong> La nouvelle génération de Forge pour les versions 1.20.2 et supérieures.</li></ul></li></ul></li><li>Cliquez sur <strong>Créer</strong>. Gens Launcher télécharge les métadonnées officielles et prépare l&#39;arborescence isolée dans <code>%AppData%\\GensLauncher\\instances\\&lt;Nom&gt;</code>.</li></ol><hr><h2 id="configuration-de-java-et-memoire-vive-ram" tabindex="-1">Configuration de Java et Mémoire Vive (RAM) <a class="header-anchor" href="#configuration-de-java-et-memoire-vive-ram" aria-label="Permalink to &quot;Configuration de Java et Mémoire Vive (RAM)&quot;">​</a></h2><p>Chaque instance peut posséder sa propre allocation de mémoire et sa propre machine virtuelle Java :</p><ol><li>Faites un clic droit sur l&#39;instance -&gt; <strong>Paramètres de l&#39;Instance</strong> (ou sélectionnez-la et cliquez sur l&#39;engrenage).</li><li><strong>Allocation RAM :</strong><ul><li><strong>Minimum conseillé (Vanilla) :</strong> 2 Go (<code>2048 Mo</code>).</li><li><strong>Conseillé pour Modpacks légers :</strong> 4 Go (<code>4096 Mo</code>).</li><li><strong>Modpacks lourds (200+ mods) :</strong> 6 à 8 Go (<code>6144</code> à <code>8192 Mo</code>).</li></ul></li><li><strong>Détection automatique de Java :</strong> Gens Launcher analyse automatiquement vos dossiers système et sélectionne la bonne version de Java requise pour votre version du jeu : <ul><li><strong>Minecraft 1.16 et antérieur :</strong> Java 8</li><li><strong>Minecraft 1.17 :</strong> Java 16</li><li><strong>Minecraft 1.18 à 1.20.4 :</strong> Java 17</li><li><strong>Minecraft 1.20.5 et supérieur :</strong> Java 21 ou Java 25 Si la version appropriée est absente de votre ordinateur, Gens Launcher vous propose de la télécharger automatiquement.</li></ul></li></ol><hr><h2 id="catalogue-de-mods-et-contenu-integre" tabindex="-1">Catalogue de Mods et Contenu Intégré <a class="header-anchor" href="#catalogue-de-mods-et-contenu-integre" aria-label="Permalink to &quot;Catalogue de Mods et Contenu Intégré&quot;">​</a></h2><p>Fini le temps où vous deviez ouvrir votre navigateur pour chercher des fichiers <code>.jar</code> suspects :</p><ol><li>Ouvrez l&#39;instance souhaitée et cliquez sur l&#39;onglet <strong>Mods</strong> (ou <strong>Ressources</strong>).</li><li>Cliquez sur le bouton <strong>Ajouter du Contenu</strong>.</li><li>Utilisez la barre de recherche connectée en temps réel aux API de <strong>Modrinth</strong> et <strong>CurseForge</strong>.</li><li>Filtrez par catégorie, version du jeu et modloader.</li><li>Cliquez sur <strong>Installer</strong> : <ul><li>Le fichier <code>.jar</code> compatible est automatiquement téléchargé et déposé dans le dossier <code>mods/</code>.</li><li>Les dépendances nécessaires sont identifiées.</li></ul></li><li>Vous pouvez également activer ou désactiver un mod d&#39;un simple interrupteur sans supprimer le fichier.</li></ol><hr><h2 id="shaders-et-packs-de-textures" tabindex="-1">Shaders et Packs de Textures <a class="header-anchor" href="#shaders-et-packs-de-textures" aria-label="Permalink to &quot;Shaders et Packs de Textures&quot;">​</a></h2><p>Le même système de catalogue intégré est disponible pour :</p><ul><li><strong>Les Shaders Packs :</strong> Recherchez des shaders populaires (Complementary, BSL, Iris Shaders) et activez-les en un clic.</li><li><strong>Les Resource Packs :</strong> Téléchargez des textures haute résolution, packs sonores ou polices d&#39;écriture directement dans le sous-dossier <code>resourcepacks/</code>.</li></ul><hr><h2 id="import-et-export-d-instances" tabindex="-1">Import et Export d&#39;Instances <a class="header-anchor" href="#import-et-export-d-instances" aria-label="Permalink to &quot;Import et Export d&#39;Instances&quot;">​</a></h2><ul><li><strong>Exporter :</strong> Vous pouvez exporter votre instance sous forme d&#39;archive <code>.zip</code> prête à être partagée avec vos amis ou sauvegardée localement.</li><li><strong>Importer :</strong> Cliquez sur <strong>Importer une Instance</strong> pour charger une archive zip compatible (format CurseForge, Modrinth Modpack ou MultiMC zip).</li></ul>',21)])])}const m=r(a,[["render",i]]);export{p as __pageData,m as default};
